using System.Collections.Generic;
using DarkFantasyMerchant.Core;
using DarkFantasyMerchant.Game;
using NUnit.Framework;
using UnityEditor;

namespace DarkFantasyMerchant.Tests.EditMode
{
    /// <summary>Checks the economy content generated by the world map setup tool.</summary>
    public class EconomyContentTests
    {
        private const string EconomyPath = "Assets/Data/Economy/Economy.asset";
        private const string BuildingsPath = "Assets/Data/Economy/Buildings.asset";
        private const string MapPath = "Assets/Data/WorldMap/WorldMap.asset";
        private const string ShipPath = "Assets/Data/Ships/MerchantShip.asset";

        private static EconomyDefinition LoadEconomy()
        {
            var economy = AssetDatabase.LoadAssetAtPath<EconomyDefinition>(EconomyPath);
            Assert.IsNotNull(economy, EconomyPath);
            return economy;
        }

        private static WorldMapDefinition LoadMap()
        {
            var map = AssetDatabase.LoadAssetAtPath<WorldMapDefinition>(MapPath);
            Assert.IsNotNull(map, MapPath);
            return map;
        }

        // The twenty goods, in the catalogue's order, with their units and base prices, active or not.
        [TestCase(0, "Céréales", GoodCategory.Food, GoodUnit.Bushel, 110, 16)]
        [TestCase(1, "Viande", GoodCategory.Food, GoodUnit.Bushel, 957, 9)]
        [TestCase(2, "Poisson", GoodCategory.Food, GoodUnit.Bushel, 440, 9)]
        [TestCase(3, "Bière", GoodCategory.Food, GoodUnit.Barrel, 34.8, 9)]
        [TestCase(4, "Sel", GoodCategory.RawMaterial, GoodUnit.Barrel, 28.5, 16)]
        [TestCase(5, "Miel", GoodCategory.RawMaterial, GoodUnit.Barrel, 110, 9)]
        [TestCase(6, "Épices", GoodCategory.RawMaterial, GoodUnit.Barrel, 280, 9)]
        [TestCase(7, "Vin", GoodCategory.RawMaterial, GoodUnit.Barrel, 220, 9)]
        [TestCase(8, "Étoffe", GoodCategory.RawMaterial, GoodUnit.Barrel, 206.8, 9)]
        [TestCase(9, "Peaux", GoodCategory.RawMaterial, GoodUnit.Barrel, 676.5, 9)]
        [TestCase(10, "Huile", GoodCategory.RawMaterial, GoodUnit.Barrel, 82.5, 9)]
        [TestCase(11, "Bois", GoodCategory.RawMaterial, GoodUnit.Bushel, 55, 11)]
        [TestCase(12, "Métal", GoodCategory.RawMaterial, GoodUnit.Barrel, 255.6, 11)]
        [TestCase(13, "Cuir", GoodCategory.RawMaterial, GoodUnit.Barrel, 224, 9)]
        [TestCase(14, "Laine", GoodCategory.RawMaterial, GoodUnit.Bushel, 880, 11)]
        [TestCase(15, "Brai", GoodCategory.RawMaterial, GoodUnit.Barrel, 55.6, 8)]
        [TestCase(16, "Fonte brute", GoodCategory.RawMaterial, GoodUnit.Bushel, 880, 8)]
        [TestCase(17, "Chanvre", GoodCategory.RawMaterial, GoodUnit.Bushel, 440, 9)]
        [TestCase(18, "Poterie", GoodCategory.RawMaterial, GoodUnit.Barrel, 171, 9)]
        [TestCase(19, "Tuiles", GoodCategory.RawMaterial, GoodUnit.Bushel, 79.8, 8)]
        public void TheCatalogue_HasTheTwentyGoods_InOrder(
            int index, string name, GoodCategory category, GoodUnit unit, double basePrice, int aiWeight)
        {
            EconomyDefinition economy = LoadEconomy();

            Assert.AreEqual(20, economy.Catalogue.Count);

            GoodDefinition good = economy.Catalogue[index].Good;
            Assert.AreEqual(name, good.DisplayName);
            Assert.AreEqual(category, good.Category);
            Assert.AreEqual(unit, good.Unit);
            Assert.AreEqual(basePrice, good.BasePrice, 1e-9);
            Assert.AreEqual(aiWeight, good.AiWeight);
            Assert.GreaterOrEqual(good.WeeklyConsumptionPerThousand.Rich, 0d);
            Assert.GreaterOrEqual(good.WeeklyConsumptionPerThousand.Wealthy, 0d);
            Assert.GreaterOrEqual(good.WeeklyConsumptionPerThousand.Poor, 0d);
            Assert.Greater(good.MaxWorkers, 0);
            Assert.Greater(good.DailyOutputPerWorker, 0d);
            Assert.Greater(good.MerchantDailyOutputPerWorker, 0d);
        }

        [Test]
        public void ABushel_TakesTenBarrels()
        {
            Assert.AreEqual(10, LoadEconomy().BarrelsPerBushel);
        }

        [Test]
        public void TheEconomy_IsUsable()
        {
            EconomyDefinition economy = LoadEconomy();

            Assert.IsTrue(economy.TryValidate(out string problem), problem);
            Assert.DoesNotThrow(() => economy.CreatePricing());
            Assert.DoesNotThrow(() => economy.CreateThresholdRule());
            Assert.DoesNotThrow(() => economy.CreateWorkforceRule());
            Assert.IsTrue(economy.TryValidateSettings(out string settingsProblem), settingsProblem);
        }

        [Test]
        public void EveryCity_ProducesSomething_OnlyGoodsOfTheCatalogue_Once()
        {
            // Inactive goods and cities count: they are switched off for a while, not removed.
            EconomyDefinition economy = LoadEconomy();

            foreach (MapCity entry in LoadMap().MapCities)
            {
                CityDefinition city = entry.City;

                Assert.Greater(city.EfficientGoods.Count + city.InefficientGoods.Count, 0, city.name);

                var seen = new HashSet<GoodDefinition>();

                foreach (GoodDefinition good in city.EfficientGoods)
                {
                    Assert.IsTrue(economy.IsInCatalogue(good), city.name);
                    Assert.IsTrue(seen.Add(good), $"{city.name}: {good.name} is listed twice");
                }

                foreach (GoodDefinition good in city.InefficientGoods)
                {
                    Assert.IsTrue(economy.IsInCatalogue(good), city.name);
                    Assert.IsTrue(seen.Add(good), $"{city.name}: {good.name} is listed twice");
                }

                Assert.DoesNotThrow(() => economy.CreateMarket(city, economy.CreatePricing(), 7), city.name);
            }
        }

        [Test]
        public void EveryGood_IsProducedEfficientlySomewhere()
        {
            var produced = new HashSet<GoodDefinition>();

            // Inactive cities count: a shortage from switching a city off is wanted.
            foreach (MapCity entry in LoadMap().MapCities)
            {
                produced.UnionWith(entry.City.EfficientGoods);
            }

            foreach (GoodDefinition good in LoadEconomy().Goods)
            {
                Assert.IsTrue(produced.Contains(good), good.name);
            }
        }

        [Test]
        public void EveryCity_StartsWith250Workers_Of4InhabitantsEach()
        {
            EconomyDefinition economy = LoadEconomy();

            Assert.AreEqual(250, economy.StartingWorkforce);
            Assert.AreEqual(4, economy.InhabitantsPerWorker);
        }

        [Test]
        public void TheEconomy_HasItsSatisfactionAndHousingSettings()
        {
            SocialRule rule = LoadEconomy().CreateSocialRule();

            Assert.AreEqual(50, rule.StartingSatisfaction);
            Assert.AreEqual(-13, rule.SatisfactionBases.Rich);
            Assert.AreEqual(-18, rule.SatisfactionBases.Wealthy);
            Assert.AreEqual(-27, rule.SatisfactionBases.Poor);
            Assert.AreEqual(2, rule.SatisfactionRise);
            Assert.AreEqual(1, rule.SatisfactionFall);
            Assert.AreEqual(9, rule.CommonSatisfaction);
            Assert.AreEqual(0.97, LoadEconomy().CreateHousingRule(SocialClass.Rich, 40, new MaterialCost[0]).Occupancy, 1e-9);
        }

        [TestCase(0, 3.15, 4.2, 5.25, 2, 4, 8)]   // Céréales
        [TestCase(7, 52.5, 13.3, 0, 5, 2, 0)]     // Vin
        [TestCase(17, 0.175, 0.105, 0.07, 0, 0, 0)] // Chanvre
        public void AGood_HasItsConsumptionAndWeights(
            int index, double rich, double wealthy, double poor, int richWeight, int wealthyWeight, int poorWeight)
        {
            GoodDefinition good = LoadEconomy().Catalogue[index].Good;

            Assert.AreEqual(rich, good.WeeklyConsumptionPerThousand.Rich, 1e-9);
            Assert.AreEqual(wealthy, good.WeeklyConsumptionPerThousand.Wealthy, 1e-9);
            Assert.AreEqual(poor, good.WeeklyConsumptionPerThousand.Poor, 1e-9);
            Assert.AreEqual(richWeight, good.SatisfactionWeights.Rich);
            Assert.AreEqual(wealthyWeight, good.SatisfactionWeights.Wealthy);
            Assert.AreEqual(poorWeight, good.SatisfactionWeights.Poor);
        }

        [Test]
        public void TheEconomy_HasItsLabourSettings()
        {
            EconomyDefinition economy = LoadEconomy();

            Assert.AreEqual(4d / 17d, economy.StartingBeggarsPerWorker, 1e-9);

            LabourRule rule = economy.CreateLabourRule();

            Assert.AreEqual(4, rule.InhabitantsPerWorker);
            Assert.AreEqual(50d, rule.BeggarSatisfaction);
            Assert.AreEqual(3, rule.BeggarTargetDivisor);
            Assert.AreEqual(8, rule.BeggarTargetMinimum);
            Assert.AreEqual(5, rule.BeggarArrivalDivisor);
            Assert.AreEqual(10, rule.BeggarDepartureDivisor);
            Assert.AreEqual(5, rule.VacancyMinimumBeggars);
            Assert.AreEqual(3, rule.VacancyMinimumFreeRoom);
            Assert.AreEqual(0.02, rule.ReserveLeakShare, 1e-9);
            Assert.AreEqual(30, rule.ReserveLeakCeiling);
        }

        [Test]
        public void TheBuildings_AreTheWorkshopAndTheHouse()
        {
            var buildings = AssetDatabase.LoadAssetAtPath<BuildingsDefinition>(BuildingsPath);
            Assert.IsNotNull(buildings, BuildingsPath);

            AssertBuilding(buildings.Workshop, 10000, 10, 30);
            Assert.AreEqual(30, buildings.WorkshopJobs);
            AssertBuilding(buildings.HouseOf(SocialClass.Poor), 5000, 10, 10);
            AssertBuilding(buildings.HouseOf(SocialClass.Wealthy), 10000, 15, 20);
            AssertBuilding(buildings.HouseOf(SocialClass.Rich), 25000, 25, 30);
            Assert.AreEqual(140, buildings.HouseRooms.Poor);
            Assert.AreEqual(70, buildings.HouseRooms.Wealthy);
            Assert.AreEqual(40, buildings.HouseRooms.Rich);
            Assert.IsTrue(buildings.TryValidate(out string problem), problem);
            Assert.IsTrue(buildings.TryCreateCost(buildings.HouseOf(SocialClass.Rich), LoadEconomy(), out _, out problem), problem);
            Assert.IsTrue(buildings.TryCreateCost(buildings.Workshop, LoadEconomy(), out _, out problem), problem);
        }

        private static void AssertBuilding(BuildingsDefinition.BuildingType building, long gold, int timber, int metal)
        {
            Assert.AreEqual(gold, building.Gold);
            Assert.AreEqual(2, building.Materials.Count);
            Assert.AreEqual("Bois", building.Materials[0].Good.DisplayName);
            Assert.AreEqual(timber, building.Materials[0].Units);
            Assert.AreEqual("Métal", building.Materials[1].Good.DisplayName);
            Assert.AreEqual(metal, building.Materials[1].Units);
        }

        [Test]
        public void MerchantShip_HoldsTwoHundredBarrels()
        {
            var ship = AssetDatabase.LoadAssetAtPath<ShipDefinition>(ShipPath);
            Assert.IsNotNull(ship, ShipPath);

            Assert.AreEqual(200, ship.CargoCapacity);
        }
    }
}
